def safe_predict(model, generator):
    """Predict features from generator, skipping corrupted images"""
    all_features = []
    all_labels = []

    for batch_idx in range(len(generator)):
        try:
            batch_images, batch_labels = generator[batch_idx]
            features = model.predict(batch_images, verbose=0)
            all_features.append(features)
            all_labels.append(batch_labels)
        except Exception as e:
            print(f"Warning: Skipping batch {batch_idx} due to error: {e}")
            continue

    if all_features:
        return np.vstack(all_features), np.vstack(all_labels)
    else:
        return np.array([]), np.array([])

